def separate_paren_groups(paren_string: str) -> List[str]:
    groups = []
    group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        group += char

        if open_braces == 0:
            groups.append(group)
            group = ""

    result = [group for group in groups if group]

    return result

